# -*- coding: utf-8 -*-
"""docs/3.4-性能预算.docx —— 按 game-docs-and-sheets-inventory.md 3.4 写。

清单要求：首屏加载时间上限、包体积上限、内存上限、帧率下限、超出时先砍什么（写明顺序）。
事实来源：src/config.ts 的 ladder.population=10000、src/core/ladder.ts 的 placementOf/cache、
src/core/league.ts 的 standings、src/ui/main.ts 的 render（innerHTML 全量重建）、产物大小。
"""
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, ROOT)

import docx_kit as k

OUT = os.path.join(ROOT, "docs", "3.4-性能预算.docx")


def main():
    doc = k.new_doc("3.4 性能预算 · v0.1 · 2026-11-05")
    k.title(
        doc,
        "电竞选手模拟器 · 性能预算",
        "上限 · 现状 · 超了砍谁 · v0.1 · 2026-11-04 初版 / 11-05 补第六节",
    )

    k.note(
        doc,
        "前提：产物是一个 89 KB 的本地 HTML，**没有任何网络请求**。所以「首屏慢」在这里几乎不存在，"
        "真正要防的是**低端手机上的计算卡顿**和**包体膨胀**。以下数字里，标「实测」的来自本机跑数，"
        "标「目标」的是预算，标「未测」的一律没在真机上验证过。",
    )

    # ---------------- 一 ----------------
    k.h1(doc, "一", "硬预算（超出即判失败）")
    k.table(
        doc,
        ["#", "指标", "上限", "现状", "怎么量"],
        [
            ["1", "产物大小", "≤ 150 KB", "88.5 KB（完整）/ 89.3 KB（切片）", "构建后看文件字节"],
            ["2", "首屏可交互", "≤ 1.0 秒", "未测（本地文件，预计 < 100ms）", "手机冷启动，掐表"],
            ["3", "单次操作响应", "≤ 100 ms", "未测（目标 50ms 内）", "点行动格到界面变化"],
            ["4", "单次全量重渲染", "≤ 50 ms", "未测", "console.time 包住 render()"],
            ["5", "内存占用", "≤ 80 MB", "未测（数据全是静态常量）", "Safari/Chrome 任务管理器"],
            ["6", "滑动帧率", "≥ 50 fps", "未测（页面基本静态，无需滚动动画）", "低端安卓实测"],
            ["7", "网络请求", "0", "0（CSS/JS 全内联、无字体、无图片）", "DevTools Network"],
            ["8", "崩溃/白屏", "0", "0（无线上监控，无法确认）", "只能靠用户反馈"],
        ],
        [1.0, 4.4, 3.0, 7.4, 5.0],
        size=9,
        caption="表 1-1　1、7 两项是实测；2–6 是目标值，一台真机都没测过",
    )

    # ---------------- 二 ----------------
    k.h1(doc, "二", "三个真正吃性能的地方")
    k.para(
        doc,
        "**① 排位名次 `placementOf()`**——全服 10000 个虚拟对手，每次都要循环算一遍「他走了 N 周之后多少分」。"
        "结果按 `(分数, 周数)` 缓存 400 条。上分一次涨约 500 分，缓存必然 miss，也就是每次上分都要跑 10000 次 `advance()`。"
        "**这是整个游戏里唯一可能卡一下的地方**，本机没测出问题，低端机上风险最高。",
    )
    k.para(
        doc,
        "**② 整页重渲染**——`src/ui/main.ts:521` 的 `render()` 每次都重建整个 `innerHTML`，"
        "没有 diff。好处是逻辑简单、不会状态错乱；代价是每次点击都要重建所有节点。"
        "目前最大的一屏是赛程页（14–17 支队的积分榜 + 之后四周），重建量仍很小。",
    )
    k.para(
        doc,
        "**③ 积分榜 `standings()`**——按队伍实力算胜率再排序，14–17 支队，每次进赛程页算一次。"
        "量大时可忽略，但如果以后每队加「逐周历史」，这里会变成 O(队 × 周)。",
    )

    # ---------------- 三 ----------------
    k.h1(doc, "三", "超预算时先砍什么（顺序固定，从上往下）")
    k.table(
        doc,
        ["#", "先砍", "省下什么", "玩家损失"],
        [
            ["1", "赛程页的「之后四周」", "一次渲染约 30 个节点", "看不见近期赛程，只知下一场"],
            ["2", "事件正文 120 字 → 80 字", "每屏排版与滚动", "梗讲不完整，最伤体验"],
            ["3", "`placementOf` 人口 10000 → 3000", "每次上分少 70% 循环", "名次跳动变粗，几乎无感"],
            ["4", "荣誉柜只显示最近 3 年", "生涯页节点数", "8 年荣誉看不全"],
            ["5", "商店八项拆成两页", "单页高度", "多一次点击"],
            ["6", "不做「之后四周」，也不做名次小数动画", "—", "已在上一步"],
        ],
        [1.0, 7.0, 6.0, 6.6],
        size=9,
        caption="表 3-1　砍的次序：先砍「信息密度」，再砍「精度」，最后才砍「内容」",
    )
    k.para(
        doc,
        "**不许砍的**：结算数值、存档写入、三格行动、事件抽卡。这四样砍了就不是同一个游戏了。",
    )

    # ---------------- 四 ----------------
    k.h1(doc, "四", "怎么验（发布前跑一遍）")
    k.table(
        doc,
        ["验什么", "怎么验", "记在哪"],
        [
            ["包体", "构建后看 `dist/index.html` 字节数，>150KB 报警", "3.3 的发布前检查第 3 步"],
            ["单次渲染耗时", "`console.time('render')` 包住 render()，连点 20 次取最大", "开发期临时加"],
            ["上分卡顿", "连点上分 5 次，感受有无掉帧", "真机"],
            ["内存", "手机任务管理器看页面占用", "真机"],
            ["首屏", "清缓存冷开，掐表到「开始生涯」可点", "真机"],
        ],
        [3.0, 9.6, 6.8],
        size=9,
    )
    k.para(
        doc,
        "**当前状态：一台真机都没测过。** 上表 4 项「未测」不是「没问题」，是「不知道」。"
        "第一次投稿前必须用一台中低端安卓跑一遍，否则这条预算表只是纸面。",
    )

    # ---------------- 五 ----------------
    k.h1(doc, "五", "与内容量的联动（改内容前先看这张）")
    k.table(
        doc,
        ["内容增加", "预计包体增量", "预计性能影响"],
        [
            ["每条事件（含 3 选项、正文 120 字）", "+1.1 KB", "无"],
            ["事件上限 60 条", "+66 KB（当前 34 条已含在内）", "抽卡时多扫几十个对象，无感"],
            ["每张截图/图片", "+30–200 KB", "**严重**，且违反「零位图」约定"],
            ["每段音频", "+50 KB 起", "**禁止**，会破坏离线单文件"],
            ["队伍数据再加 5 个赛季", "+12 KB", "无"],
        ],
        [7.0, 6.4, 6.0],
        size=9,
    )
    k.note(
        doc,
        "结论：**内容（文字）几乎不要钱，位图和音频要命。** 所以「零音频、零位图」不是审美选择，是性能预算。"
        "事件从 34 条写到 60 条，包体大约 105 KB，仍在 150 KB 内。",
    )

    # ---------------- 六 ----------------
    k.h1(doc, "六", "决定：不测真机，线不动（2026-11-05）")
    k.para(
        doc,
        "**已拍板，两条：** ① 不为性能单独上真机测（也不借 09 号的设备顺手量），发布前以本机 PC 数据为依据；"
        "② 上面 8 条预算线一条不改——150 KB / 100 ms / 1.0 s / 80 MB / 50 fps 维持原样。",
    )
    k.para(
        doc,
        "**出处：** 用户原话「不测」「不动」（2026-11-05，回答 20 号 ticket 的两问）。测法与原始数字见"
        "「20-性能预算-讲懂版.docx」。",
    )
    k.note(
        doc,
        "后果说清：表 1 第 2–6 项仍是「未测」，**手机上到底卡不卡，现在没有答案**（本机操作 0.5–5.6 ms，"
        "按 10 倍粗算手机约 56 ms，仍在 100 ms 内，但那是推算）。包体继续按 150 KB 管，超了再回来改线。"
        "若以后玩家反馈卡顿，重开 20 号 ticket 即可，不用重写这份文档。",
    )

    doc.save(OUT)
    print("saved", OUT)


if __name__ == "__main__":
    main()
